mapper.select:
SELECT id, title, source, source_ref, chunk_count, file_size, content, original_content,
       fetch_status, translation_status, storage_status, vector_status, pipeline_error, create_time
FROM knowledge_document WHERE id = #{id}

SELECT id, title, source, source_ref, chunk_count, file_size, content, original_content,
       fetch_status, translation_status, storage_status, vector_status, pipeline_error, create_time
FROM knowledge_document WHERE source_ref = #{sourceRef}

SELECT id, title, source, source_ref, chunk_count, file_size, create_time
FROM knowledge_document
WHERE source = 'GITHUB' AND (source_ref LIKE '%|week' OR source_ref LIKE '%|new') AND create_time < #{beforeDate}
